insert into public.competitions(sport,name,country,external_id) values('football','Premier League','England','demo-premier-league'),('football','Champions League','Europe','demo-champions-league'),('football','Serie A','Italy','demo-serie-a') on conflict(external_id) do update set name=excluded.name;
insert into public.events(competition_id,home_name,away_name,kickoff_at,external_id) select c.id,x.home_name,x.away_name,now()+x.offset_time,x.external_id from(values('demo-premier-league','Arsenal','Liverpool',interval '1 day','demo-arsenal-liverpool'),('demo-champions-league','Real Madrid','Inter',interval '1 day 3 hours','demo-real-inter'),('demo-serie-a','Milan','Juventus',interval '2 days','demo-milan-juventus'))as x(competition_external_id,home_name,away_name,offset_time,external_id) join public.competitions c on c.external_id=x.competition_external_id on conflict(external_id) do update set kickoff_at=excluded.kickoff_at,status='scheduled',home_score=null,away_score=null;
insert into public.markets(event_id,market_type,selection,reference_odds,captured_at,provider) select e.id,'match_winner',x.selection,x.odds,now(),'demo-feed' from(values('demo-arsenal-liverpool','Arsenal',2.15::numeric),('demo-arsenal-liverpool','Draw',3.40::numeric),('demo-arsenal-liverpool','Liverpool',3.10::numeric),('demo-real-inter','Real Madrid',1.92::numeric),('demo-real-inter','Draw',3.55::numeric),('demo-real-inter','Inter',4.10::numeric),('demo-milan-juventus','Milan',2.45::numeric),('demo-milan-juventus','Draw',3.20::numeric),('demo-milan-juventus','Juventus',2.90::numeric))as x(event_external_id,selection,odds) join public.events e on e.external_id=x.event_external_id;
